/* ---- server ---------------------------------------------------------- */

/* Handlers: return OK and fill the results, or an ERR_* for the client.
 * A NULL handler answers ERR_NOT_SUPPORTED. A `later` method's handler
 * also gets the request's txn, and may return IDL_LATER and answer it
 * with devmgr_reply_<method> (now, or later from anywhere). */
struct devmgr_ops {
    status_t (*status)(void *ctx, uint32_t *out_bound, uint32_t *out_failed, uint32_t *out_skipped);
    status_t (*get_service)(void *ctx, uint8_t kind, uint32_t a, uint32_t b, uint32_t n, handle_t *out_service);
    status_t (*get_driver)(void *ctx, uint8_t kind, uint32_t a, uint32_t b, uint32_t n, handle_t *out_process, handle_t *out_job, uint32_t *out_pci_index);
    status_t (*get_function)(void *ctx, uint8_t kind, uint32_t a, uint32_t b, uint32_t n, handle_t *out_function);
    status_t (*supervision)(void *ctx, uint8_t kind, uint32_t a, uint32_t b, uint32_t n, uint32_t *out_state, uint32_t *out_restarts, uint32_t *out_backoff_ms, uint32_t *out_dma_quarantined, uint32_t *out_dma_changed);
};

/* Answer the devmgr.status request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t devmgr_reply_status(struct idl_txn idl_txn, status_t idl_st, uint32_t bound, uint32_t failed, uint32_t skipped)
{
    struct devmgr_status_rep idl_r;
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    idl_r.status = idl_st;
    if (idl_st != OK)
        return idl_reply_write(idl_txn, &idl_r, sizeof(struct idl_rep_hdr), NULL, 0);
    idl_r.bound = bound;
    idl_r.failed = failed;
    idl_r.skipped = skipped;
    return idl_reply_write(idl_txn, &idl_r, sizeof(idl_r), NULL, 0);
}

/* Answer the devmgr.get_service request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t devmgr_reply_get_service(struct idl_txn idl_txn, status_t idl_st, handle_t service)
{
    handle_t idl_hs[1] = { service };
    _Alignas(8) uint8_t idl_b0[8];
    struct devmgr_get_service_rep *idl_r = (struct devmgr_get_service_rep *)idl_b0;
    uint32_t idl_rn = sizeof(*idl_r);
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !(service != HANDLE_INVALID))
        idl_st = ERR_INTERNAL;
    idl_r->status = idl_st;
    if (idl_st != OK) {
        if (idl_hs[0] != HANDLE_INVALID)
            drv_handle_close(idl_hs[0]);
        idl_rn = sizeof(struct idl_rep_hdr);
    }
    status_t idl_ws = idl_reply_write(idl_txn, idl_b0, idl_rn, idl_st == OK ? idl_hs : NULL, idl_st == OK ? 1 : 0);
    return idl_ws;
}

/* Answer the devmgr.get_driver request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t devmgr_reply_get_driver(struct idl_txn idl_txn, status_t idl_st, handle_t process, handle_t job, uint32_t pci_index)
{
    handle_t idl_hs[2] = { process, job };
    _Alignas(8) uint8_t idl_b0[12];
    struct devmgr_get_driver_rep *idl_r = (struct devmgr_get_driver_rep *)idl_b0;
    uint32_t idl_rn = sizeof(*idl_r);
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !(process != HANDLE_INVALID && job != HANDLE_INVALID))
        idl_st = ERR_INTERNAL;
    idl_r->pci_index = pci_index;
    idl_r->status = idl_st;
    if (idl_st != OK) {
        if (idl_hs[0] != HANDLE_INVALID)
            drv_handle_close(idl_hs[0]);
        if (idl_hs[1] != HANDLE_INVALID)
            drv_handle_close(idl_hs[1]);
        idl_rn = sizeof(struct idl_rep_hdr);
    }
    status_t idl_ws = idl_reply_write(idl_txn, idl_b0, idl_rn, idl_st == OK ? idl_hs : NULL, idl_st == OK ? 2 : 0);
    return idl_ws;
}

/* Answer the devmgr.get_function request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t devmgr_reply_get_function(struct idl_txn idl_txn, status_t idl_st, handle_t function)
{
    handle_t idl_hs[1] = { function };
    _Alignas(8) uint8_t idl_b0[8];
    struct devmgr_get_function_rep *idl_r = (struct devmgr_get_function_rep *)idl_b0;
    uint32_t idl_rn = sizeof(*idl_r);
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !(function != HANDLE_INVALID))
        idl_st = ERR_INTERNAL;
    idl_r->status = idl_st;
    if (idl_st != OK) {
        if (idl_hs[0] != HANDLE_INVALID)
            drv_handle_close(idl_hs[0]);
        idl_rn = sizeof(struct idl_rep_hdr);
    }
    status_t idl_ws = idl_reply_write(idl_txn, idl_b0, idl_rn, idl_st == OK ? idl_hs : NULL, idl_st == OK ? 1 : 0);
    return idl_ws;
}

/* Answer the devmgr.supervision request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t devmgr_reply_supervision(struct idl_txn idl_txn, status_t idl_st, uint32_t state, uint32_t restarts, uint32_t backoff_ms, uint32_t dma_quarantined, uint32_t dma_changed)
{
    struct devmgr_supervision_rep idl_r;
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    idl_r.status = idl_st;
    if (idl_st != OK)
        return idl_reply_write(idl_txn, &idl_r, sizeof(struct idl_rep_hdr), NULL, 0);
    idl_r.state = state;
    idl_r.restarts = restarts;
    idl_r.backoff_ms = backoff_ms;
    idl_r.dma_quarantined = dma_quarantined;
    idl_r.dma_changed = dma_changed;
    return idl_reply_write(idl_txn, &idl_r, sizeof(idl_r), NULL, 0);
}

/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (DEVMGR_REP_MAX bytes) and the handles it carries
 * into rhs (DEVMGR_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the request has no txid, or a `later`
 * handler answers it itself). No I/O; the caller sends the reply with the
 * handles, or closes them if it never sends it. */
static inline uint32_t devmgr_dispatch_on(handle_t ch, const struct devmgr_ops *ops, void *ctx,
                                          const void *req, uint32_t n, void *rep, handle_t *rhs,
                                          uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    (void)ch;
    if (n < sizeof(uint32_t))
        return 0;
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    if (n < sizeof(struct idl_req_hdr))
        return sizeof(*idl_h);
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case DEVMGR_STATUS: {
        const struct devmgr_status_req *idl_q = (const struct devmgr_status_req *)req;
        struct devmgr_status_rep *idl_r = (struct devmgr_status_rep *)rep;
        uint32_t out_bound = 0;
        uint32_t out_failed = 0;
        uint32_t out_skipped = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->status) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->status(ctx, &out_bound, &out_failed, &out_skipped);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->bound = out_bound;
        idl_r->failed = out_failed;
        idl_r->skipped = out_skipped;
        return sizeof(*idl_r);
    }
    case DEVMGR_GET_SERVICE: {
        const struct devmgr_get_service_req *idl_q = (const struct devmgr_get_service_req *)req;
        struct devmgr_get_service_rep *idl_r = (struct devmgr_get_service_rep *)rep;
        handle_t out_service = HANDLE_INVALID;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->get_service) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->get_service(ctx, idl_q->kind, idl_q->a, idl_q->b, idl_q->n, &out_service);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_service != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_service != HANDLE_INVALID)
                drv_handle_close(out_service);
            return sizeof(*idl_h);
        }
        rhs[0] = out_service;
        *rhn = 1;
        return sizeof(*idl_r);
    }
    case DEVMGR_GET_DRIVER: {
        const struct devmgr_get_driver_req *idl_q = (const struct devmgr_get_driver_req *)req;
        struct devmgr_get_driver_rep *idl_r = (struct devmgr_get_driver_rep *)rep;
        handle_t out_process = HANDLE_INVALID;
        handle_t out_job = HANDLE_INVALID;
        uint32_t out_pci_index = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->get_driver) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->get_driver(ctx, idl_q->kind, idl_q->a, idl_q->b, idl_q->n, &out_process, &out_job, &out_pci_index);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_process != HANDLE_INVALID && out_job != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_process != HANDLE_INVALID)
                drv_handle_close(out_process);
            if (out_job != HANDLE_INVALID)
                drv_handle_close(out_job);
            return sizeof(*idl_h);
        }
        rhs[0] = out_process;
        rhs[1] = out_job;
        *rhn = 2;
        idl_r->pci_index = out_pci_index;
        return sizeof(*idl_r);
    }
    case DEVMGR_GET_FUNCTION: {
        const struct devmgr_get_function_req *idl_q = (const struct devmgr_get_function_req *)req;
        struct devmgr_get_function_rep *idl_r = (struct devmgr_get_function_rep *)rep;
        handle_t out_function = HANDLE_INVALID;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->get_function) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->get_function(ctx, idl_q->kind, idl_q->a, idl_q->b, idl_q->n, &out_function);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_function != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_function != HANDLE_INVALID)
                drv_handle_close(out_function);
            return sizeof(*idl_h);
        }
        rhs[0] = out_function;
        *rhn = 1;
        return sizeof(*idl_r);
    }
    case DEVMGR_SUPERVISION: {
        const struct devmgr_supervision_req *idl_q = (const struct devmgr_supervision_req *)req;
        struct devmgr_supervision_rep *idl_r = (struct devmgr_supervision_rep *)rep;
        uint32_t out_state = 0;
        uint32_t out_restarts = 0;
        uint32_t out_backoff_ms = 0;
        uint32_t out_dma_quarantined = 0;
        uint32_t out_dma_changed = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->supervision) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->supervision(ctx, idl_q->kind, idl_q->a, idl_q->b, idl_q->n, &out_state, &out_restarts, &out_backoff_ms, &out_dma_quarantined, &out_dma_changed);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->state = out_state;
        idl_r->restarts = out_restarts;
        idl_r->backoff_ms = out_backoff_ms;
        idl_r->dma_quarantined = out_dma_quarantined;
        idl_r->dma_changed = out_dma_changed;
        return sizeof(*idl_r);
    }
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* devmgr_dispatch_on without the channel (the protocol has no `later` method). */
static inline uint32_t devmgr_dispatch(const struct devmgr_ops *ops, void *ctx, const void *req, uint32_t n,
                                       void *rep, handle_t *rhs, uint32_t *rhn)
{
    return devmgr_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* Take the next message on ch into slot (idl_take), a slot with room for
 * the protocol's biggest request (ERR_INVALID_ARGS if it has less). The
 * reply waiting in *rep (NULL or empty: none) goes out first in the same
 * system call (idl_take_after). It never waits: ERR_SHOULD_WAIT when
 * nothing is queued. */
static inline status_t devmgr_take_slot(handle_t ch, const struct idl_slot *slot,
                                        struct idl_reply *rep)
{
    if (slot->qcap < DEVMGR_REQ_MAX)
        return ERR_INVALID_ARGS;
    if (rep && rep->ch != HANDLE_INVALID)
        return idl_take_after(ch, slot, rep);
    return idl_take(ch, slot);
}

/* Run the request in slot (taken by devmgr_take_slot, or found there by a
 * successor), which came on ch: as devmgr_dispatch_on, its reply built
 * in slot->r and the handles that reply carries put into rhs
 * (DEVMGR_REP_HANDLES slots; *rhn of them). A request that carried handles is
 * answered ERR_INVALID_ARGS without its handler seeing it. Returns the
 * reply's length: 0 means no reply (no txid, or a `later` handler
 * answers it itself). No I/O; the caller sends the reply with the handles,
 * or closes them if it never sends it. */
static inline uint32_t devmgr_run_slot(handle_t ch, const struct idl_slot *slot,
                                       const struct devmgr_ops *ops, void *ctx, handle_t *rhs, uint32_t *rhn)
{
    *rhn = 0;
    if (*slot->n >= sizeof(uint32_t) && *slot->nh)
        return idl_refuse(slot);
    return devmgr_dispatch_on(ch, ops, ctx, slot->q, *slot->n, slot->r, rhs, rhn);
}

/* Is the method with this wire ordinal idempotent (its keyword in the
 * .idl): run again on the state its first run left, it gives the same
 * result and the same answer? A server that keeps nothing across a
 * restart may run such a request again; any other it answers with an
 * error. (No server reads it yet: it is for the drivers that outlive
 * their process, after M12.) */
static inline bool devmgr_idempotent(uint32_t ordinal)
{
    (void)ordinal;
    return false;   /* no method is marked */
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t devmgr_serve_one(handle_t ch, const struct devmgr_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[DEVMGR_REQ_MAX];
    _Alignas(8) uint8_t idl_r[DEVMGR_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, sizeof(idl_q), &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL)
        return idl_drain(ch, idl_n, idl_nh);
    if (idl_st != OK)
        return idl_st;
    if (idl_nh) {
        idl_close_all(idl_hs, idl_nh);
        idl_reply_status(ch, idl_q, idl_n, ERR_INVALID_ARGS);
        return OK;
    }
    handle_t idl_rhs[IDL_REP_HANDLES];
    uint32_t idl_rhn = 0;
    uint32_t idl_rn = devmgr_dispatch_on(ch, ops, ctx, idl_q, idl_n, idl_r, idl_rhs, &idl_rhn);
    if (!idl_rn)
        idl_close_all(idl_rhs, idl_rhn);   /* no reply: never sent */
    else   /* the reply's handles are gone whatever the write's status */
        (void)drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn);
    return OK;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request
 * (idl_serve_next). */
static inline status_t devmgr_serve(handle_t ch, const struct devmgr_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[DEVMGR_REQ_MAX];
    _Alignas(8) uint8_t idl_r[DEVMGR_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = sizeof(idl_q), .r = idl_r, .rhs = idl_rhs,
    };
    for (;;) {
        status_t idl_st = idl_serve_next(&idl_s);
        if (idl_st == ERR_PEER_CLOSED)
            return OK;
        if (idl_st != OK)
            return idl_st;
        idl_s.rn = devmgr_dispatch_on(ch, ops, ctx, idl_q, idl_s.n, idl_r, idl_rhs, &idl_s.rhn);
    }
}


/* ==== protocol `devmgrctl` (id 91) ==========================================
 *
 * devmgrctl: the control channel's own methods (init's; the tests'). The
 * query methods above go to it too (above, "CONTROL").
 *
 * Reconnect: as devmgr's. */

#define DEVMGRCTL_PROTOCOL_ID 91u
#define DEVMGRCTL_KILL             0x005b0001u
#define DEVMGRCTL_REBIND           0x005b0002u
#define DEVMGRCTL_RELEASE          0x005b0003u
