    uint32_t idl_n = 0;
    idl_q.txid = 0;
    idl_q.ordinal = DEVMGRCTL_RELEASE;
    idl_q.kind = kind;
    idl_q.a = a;
    idl_q.b = b;
    idl_q.n = n;
