/* devmgrctl_set_input_until and _within: idl_t is a deadline, or with idl_within a
 * timeout from when the call starts (the kernel's clock). */
static inline status_t devmgrctl_set_input_call(handle_t ch, bool idl_within, uint64_t idl_t, handle_t input)
{
    _Alignas(8) uint8_t idl_b0[8];
    _Alignas(8) uint8_t idl_b1[8];
    struct devmgrctl_set_input_req *idl_q = (struct devmgrctl_set_input_req *)idl_b0;
    const struct devmgrctl_set_input_rep *idl_r = (const struct devmgrctl_set_input_rep *)idl_b1;
    uint32_t idl_qn = sizeof(*idl_q), idl_o = sizeof(*idl_r);
    uint32_t idl_got[2] = { 0, 0 };   /* bytes, handles: in a row, one copy-out */
    status_t idl_st = OK;
    idl_q->txid = 0;
    idl_q->ordinal = DEVMGRCTL_SET_INPUT;
    handle_t idl_wh[1];
    uint32_t idl_wn = 0;
    if (idl_st == OK) {
        idl_wh[idl_wn++] = input;
        idl_st = idl_call_h(ch, idl_b0, idl_qn, idl_wh, idl_wn, idl_b1, 8, &idl_got[0], NULL, 0, &idl_got[1],
                            idl_within, idl_t);
    } else {   /* never sent: the handles are still ours */
        if (input != HANDLE_INVALID)
            drv_handle_close(input);
    }
    if (idl_st == OK)
        idl_st = idl_rep_status(idl_b1, idl_got[0], sizeof(*idl_r));
    (void)idl_o;
    return idl_st;
}
