/* ---- server ---------------------------------------------------------- */

/* Handlers: return OK and fill the results, or an ERR_* for the client.
 * A NULL handler answers ERR_NOT_SUPPORTED. A `later` method's handler
 * also gets the request's txn, and may return IDL_LATER and answer it
 * with devmgrctl_reply_<method> (now, or later from anywhere). */
struct devmgrctl_ops {
    status_t (*kill)(void *ctx, uint8_t kind, uint32_t a, uint32_t b, uint32_t n, uint64_t *out_koid);
    status_t (*rebind)(void *ctx, uint8_t kind, uint32_t a, uint32_t b, uint32_t n);
    status_t (*release)(void *ctx, uint8_t kind, uint32_t a, uint32_t b, uint32_t n);
    status_t (*release_usb)(void *ctx, uint32_t dev, uint32_t iface, handle_t *out_usb);
    status_t (*driver_view)(void *ctx, uint8_t kind, uint32_t a, uint32_t b, uint32_t n, handle_t *out_function, uint32_t *out_bar_mask);
    status_t (*driver_bar)(void *ctx, uint8_t kind, uint32_t a, uint32_t b, uint32_t n, uint8_t bar, handle_t *out_bar);
    status_t (*test_driver)(void *ctx);
    status_t (*set_input)(void *ctx, handle_t input);
    status_t (*set_volumes)(void *ctx, handle_t disks);
    status_t (*device_channel)(void *ctx, uint8_t kind, uint32_t a, uint32_t b, uint32_t n, handle_t *out_device);
    status_t (*shutdown)(void *ctx);
    status_t (*kill_process)(void *ctx, uint64_t koid);
};

/* Answer the devmgrctl.kill request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t devmgrctl_reply_kill(struct idl_txn idl_txn, status_t idl_st, uint64_t koid)
{
    struct devmgrctl_kill_rep idl_r;
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    idl_r.status = idl_st;
    if (idl_st != OK)
        return idl_reply_write(idl_txn, &idl_r, sizeof(struct idl_rep_hdr), NULL, 0);
    idl_r.koid = koid;
    return idl_reply_write(idl_txn, &idl_r, sizeof(idl_r), NULL, 0);
}

