/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (DEVMGRCTL_REP_MAX bytes) and the handles it carries
 * into rhs (DEVMGRCTL_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the request has no txid, or a `later`
 * handler answers it itself). No I/O; the caller sends the reply with the
 * handles, or closes them if it never sends it.
 * The idl_nh handles at idl_hs (the call's arguments) are taken in every
 * case: given to its handler, or closed (the handler owns them, whatever it
 * returns). */
static inline uint32_t devmgrctl_dispatch_h(handle_t ch, const struct devmgrctl_ops *ops, void *ctx,
                                            const void *req, uint32_t n, const handle_t *idl_hs, uint32_t idl_nh,
                                            void *rep, handle_t *rhs, uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    (void)ch;
    if (n < sizeof(uint32_t)) {
        idl_close_all(idl_hs, idl_nh);
        return 0;
    }
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    if (n < sizeof(struct idl_req_hdr)) {
        idl_close_all(idl_hs, idl_nh);
        return sizeof(*idl_h);
    }
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case DEVMGRCTL_KILL: {
        const struct devmgrctl_kill_req *idl_q = (const struct devmgrctl_kill_req *)req;
        struct devmgrctl_kill_rep *idl_r = (struct devmgrctl_kill_rep *)rep;
        uint64_t out_koid = 0;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->kill) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->kill(ctx, idl_q->kind, idl_q->a, idl_q->b, idl_q->n, &out_koid);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->koid = out_koid;
        return sizeof(*idl_r);
    }
    case DEVMGRCTL_REBIND: {
        const struct devmgrctl_rebind_req *idl_q = (const struct devmgrctl_rebind_req *)req;
        struct devmgrctl_rebind_rep *idl_r = (struct devmgrctl_rebind_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->rebind) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->rebind(ctx, idl_q->kind, idl_q->a, idl_q->b, idl_q->n);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case DEVMGRCTL_RELEASE: {
        const struct devmgrctl_release_req *idl_q = (const struct devmgrctl_release_req *)req;
        struct devmgrctl_release_rep *idl_r = (struct devmgrctl_release_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->release) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->release(ctx, idl_q->kind, idl_q->a, idl_q->b, idl_q->n);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case DEVMGRCTL_RELEASE_USB: {
        const struct devmgrctl_release_usb_req *idl_q = (const struct devmgrctl_release_usb_req *)req;
        struct devmgrctl_release_usb_rep *idl_r = (struct devmgrctl_release_usb_rep *)rep;
        handle_t out_usb = HANDLE_INVALID;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->release_usb) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->release_usb(ctx, idl_q->dev, idl_q->iface, &out_usb);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_usb != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_usb != HANDLE_INVALID)
                drv_handle_close(out_usb);
            return sizeof(*idl_h);
        }
        rhs[0] = out_usb;
        *rhn = 1;
        return sizeof(*idl_r);
    }
    case DEVMGRCTL_DRIVER_VIEW: {
        const struct devmgrctl_driver_view_req *idl_q = (const struct devmgrctl_driver_view_req *)req;
        struct devmgrctl_driver_view_rep *idl_r = (struct devmgrctl_driver_view_rep *)rep;
        handle_t out_function = HANDLE_INVALID;
        uint32_t out_bar_mask = 0;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->driver_view) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->driver_view(ctx, idl_q->kind, idl_q->a, idl_q->b, idl_q->n, &out_function, &out_bar_mask);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_function != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_function != HANDLE_INVALID)
                drv_handle_close(out_function);
            return sizeof(*idl_h);
        }
        rhs[0] = out_function;
        *rhn = 1;
        idl_r->bar_mask = out_bar_mask;
        return sizeof(*idl_r);
    }
    case DEVMGRCTL_DRIVER_BAR: {
        const struct devmgrctl_driver_bar_req *idl_q = (const struct devmgrctl_driver_bar_req *)req;
        struct devmgrctl_driver_bar_rep *idl_r = (struct devmgrctl_driver_bar_rep *)rep;
        handle_t out_bar = HANDLE_INVALID;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->driver_bar) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->driver_bar(ctx, idl_q->kind, idl_q->a, idl_q->b, idl_q->n, idl_q->bar, &out_bar);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_bar != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_bar != HANDLE_INVALID)
                drv_handle_close(out_bar);
            return sizeof(*idl_h);
        }
        rhs[0] = out_bar;
        *rhn = 1;
        return sizeof(*idl_r);
    }
    case DEVMGRCTL_TEST_DRIVER: {
        const struct devmgrctl_test_driver_req *idl_q = (const struct devmgrctl_test_driver_req *)req;
        struct devmgrctl_test_driver_rep *idl_r = (struct devmgrctl_test_driver_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->test_driver) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->test_driver(ctx);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case DEVMGRCTL_SET_INPUT: {
        const struct devmgrctl_set_input_req *idl_q = (const struct devmgrctl_set_input_req *)req;
        struct devmgrctl_set_input_rep *idl_r = (struct devmgrctl_set_input_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q) || idl_nh != 1) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->set_input) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        if (!(idl_handle_is(idl_hs[0], IDL_OBJ_CHANNEL))) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_WRONG_TYPE;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->set_input(ctx, idl_hs[0]);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case DEVMGRCTL_SET_VOLUMES: {
        const struct devmgrctl_set_volumes_req *idl_q = (const struct devmgrctl_set_volumes_req *)req;
        struct devmgrctl_set_volumes_rep *idl_r = (struct devmgrctl_set_volumes_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q) || idl_nh != 1) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->set_volumes) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        if (!(idl_handle_is(idl_hs[0], IDL_OBJ_CHANNEL))) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_WRONG_TYPE;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->set_volumes(ctx, idl_hs[0]);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case DEVMGRCTL_DEVICE_CHANNEL: {
        const struct devmgrctl_device_channel_req *idl_q = (const struct devmgrctl_device_channel_req *)req;
        struct devmgrctl_device_channel_rep *idl_r = (struct devmgrctl_device_channel_rep *)rep;
        handle_t out_device = HANDLE_INVALID;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->device_channel) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->device_channel(ctx, idl_q->kind, idl_q->a, idl_q->b, idl_q->n, &out_device);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_device != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_device != HANDLE_INVALID)
                drv_handle_close(out_device);
            return sizeof(*idl_h);
        }
        rhs[0] = out_device;
        *rhn = 1;
        return sizeof(*idl_r);
    }
    case DEVMGRCTL_SHUTDOWN: {
        const struct devmgrctl_shutdown_req *idl_q = (const struct devmgrctl_shutdown_req *)req;
        struct devmgrctl_shutdown_rep *idl_r = (struct devmgrctl_shutdown_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->shutdown) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->shutdown(ctx);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case DEVMGRCTL_KILL_PROCESS: {
        const struct devmgrctl_kill_process_req *idl_q = (const struct devmgrctl_kill_process_req *)req;
        struct devmgrctl_kill_process_rep *idl_r = (struct devmgrctl_kill_process_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->kill_process) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->kill_process(ctx, idl_q->koid);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    }
    idl_close_all(idl_hs, idl_nh);
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* devmgrctl_dispatch_h without handles (a loop of your own that reads none:
 * an event or call that takes some is then refused). */
static inline uint32_t devmgrctl_dispatch_on(handle_t ch, const struct devmgrctl_ops *ops, void *ctx,
                                             const void *req, uint32_t n, void *rep, handle_t *rhs,
                                             uint32_t *rhn)
{
    return devmgrctl_dispatch_h(ch, ops, ctx, req, n, NULL, 0, rep, rhs, rhn);
}

/* devmgrctl_dispatch_on without the channel (the protocol has no `later` method). */
static inline uint32_t devmgrctl_dispatch(const struct devmgrctl_ops *ops, void *ctx, const void *req, uint32_t n,
                                          void *rep, handle_t *rhs, uint32_t *rhn)
{
    return devmgrctl_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* Take the next message on ch into slot (idl_take), a slot with room for
 * the protocol's biggest request (ERR_INVALID_ARGS if it has less). The
 * reply waiting in *rep (NULL or empty: none) goes out first in the same
 * system call (idl_take_after). It never waits: ERR_SHOULD_WAIT when
 * nothing is queued. */
static inline status_t devmgrctl_take_slot(handle_t ch, const struct idl_slot *slot,
                                           struct idl_reply *rep)
{
    if (slot->qcap < DEVMGRCTL_REQ_MAX)
        return ERR_INVALID_ARGS;
    if (rep && rep->ch != HANDLE_INVALID)
        return idl_take_after(ch, slot, rep);
    return idl_take(ch, slot);
}

/* Run the message in slot (taken by devmgrctl_take_slot, or found there by a
 * successor), which came on ch: as devmgrctl_dispatch_h, its reply built in
 * slot->r and the handles that reply carries put into rhs
 * (DEVMGRCTL_REP_HANDLES slots; *rhn of them). The handles it carried
 * (*slot->nh in slot->hs) are taken: given to a handler or closed,
 * *slot->nh 0 after. Returns the reply's length: 0 means no reply
 * (no txid, an event, or a `later` handler answers it itself). No I/O;
 * the caller sends the reply with the handles, or closes them if it
 * never sends it. */
static inline uint32_t devmgrctl_run_slot(handle_t ch, const struct idl_slot *slot,
                                          const struct devmgrctl_ops *ops, void *ctx, handle_t *rhs, uint32_t *rhn)
{
    uint32_t idl_nh = *slot->nh;
    *slot->nh = 0;
    return devmgrctl_dispatch_h(ch, ops, ctx, slot->q, *slot->n, slot->hs, idl_nh, slot->r,
                          rhs, rhn);
}

/* Is the method with this wire ordinal idempotent (its keyword in the
 * .idl): run again on the state its first run left, it gives the same
 * result and the same answer? A server that keeps nothing across a
 * restart may run such a request again; any other it answers with an
 * error. (No server reads it yet: it is for the drivers that outlive
 * their process, after M12.) */
static inline bool devmgrctl_idempotent(uint32_t ordinal)
{
    (void)ordinal;
    return false;   /* no method is marked */
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t devmgrctl_serve_one(handle_t ch, const struct devmgrctl_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[DEVMGRCTL_REQ_MAX];
    _Alignas(8) uint8_t idl_r[DEVMGRCTL_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, DEVMGRCTL_REQ_MAX, &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL) {
        idl_st = idl_drain(ch, idl_n, idl_nh);
    } else if (idl_st == OK) {
        handle_t idl_rhs[IDL_REP_HANDLES];
        uint32_t idl_rhn = 0;
        uint32_t idl_rn = devmgrctl_dispatch_h(ch, ops, ctx, idl_q, idl_n, idl_hs, idl_nh, idl_r,
                                         idl_rhs, &idl_rhn);
        if (!idl_rn)
            idl_close_all(idl_rhs, idl_rhn);   /* no reply: never sent */
        else   /* the reply's handles are gone whatever the write's status */
            (void)drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn);
    }
    return idl_st;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request
 * (idl_serve_next). */
static inline status_t devmgrctl_serve(handle_t ch, const struct devmgrctl_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[DEVMGRCTL_REQ_MAX];
    _Alignas(8) uint8_t idl_r[DEVMGRCTL_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES], idl_hs[IDL_READ_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = DEVMGRCTL_REQ_MAX, .r = idl_r, .rhs = idl_rhs,
        .hs = idl_hs, .hcap = IDL_READ_HANDLES,
    };
    status_t idl_st;
    while ((idl_st = idl_serve_next(&idl_s)) == OK)
        idl_s.rn = devmgrctl_dispatch_h(ch, ops, ctx, idl_q, idl_s.n, idl_hs, idl_s.nh, idl_r,
                                  idl_rhs, &idl_s.rhn);
    return idl_st == ERR_PEER_CLOSED ? OK : idl_st;
}
